from taf.fdsw.rc.clients.http.http_client import RCHttpClient
from taf.fdsw.rc.interfaces.FDSW18A.fdsw import FDSW18A
from taf.fdsw.rc.interfaces.FDSW19.autoconnection import AutoConfiguration19
from taf.fdsw.rc.interfaces.FDSW19.diagnostics import Diagnostics19


class FDSW19(FDSW18A):
    API_VERSION = "1.1"
    API_SCHEMA_VERSION = "2.0"
    VERSION_NAME = 'FDSW19'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW19, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                     secure=secure)
        self._client = RCHttpClient(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
            secure=secure,
            api_version=self.API_VERSION,
            api_schema_version=self.API_SCHEMA_VERSION
        )

        self._client.connect()
        self.autoconnection = AutoConfiguration19(client=self._client)
        self.diagnostics = Diagnostics19(client=self._client)
